{"intent":"Animate the 5,600-kilometer fence as a length comparison, then resolve it into a simple diagram of the barrier separating desert predators from the fertile south.","beats":[{"start":0,"end":1.6,"action":"A continuous wire barrier draws across the frame as “5,600 km” appears above it."},{"start":1.6,"end":3.3,"action":"A shorter, unscaled comparison line enters beneath the fence; the spoken Great Wall comparison is made visible."},{"start":3.3,"end":6,"action":"The comparison gives way to an abstract desert-versus-fertile-south diagram. A predator approaches the continuous fence and stops; the final arrangement holds."}],"handoff":{"opening":"Establishes the fence immediately as a long, continuous barrier rather than repeating a title card.","persistentElements":["The continuous wire barrier","The contrast between desert and fertile south"],"endState":"A horizontal fence divides the warm-toned desert above from the green fertile south below; a predator is halted on the desert side, and both region labels remain visible.","motionVector":"The approach stops at the barrier, followed by a deliberate hold through the cut.","nextOpportunity":"The next scene could carry the barrier motif into footage or another explanation of its consequences."},"code":"import { AbsoluteFill, Img, OffthreadVideo, interpolate, staticFile, useCurrentFrame, useVideoConfig } from 'remotion';

export default function MotionScene({scene, context}: {scene:any; context:any}) {
  const frame = useCurrentFrame();
  const {fps} = useVideoConfig();
  const asset = scene.asset ?? scene.selectedAsset ?? (Array.isArray(scene.assets) ? scene.assets[0] : null);
  const src = asset?.src;
  const kind = String(asset?.type ?? asset?.mediaType ?? asset?.kind ?? '').toLowerCase();
  const isVideo = kind.includes('video') || /\.(mp4|mov|webm|m4v)(\?.*)?$/i.test(String(src ?? ''));
  const hasMapBackground = scene.map != null || (scene.backgroundIndex !== undefined && scene.backgroundIndex !== null);
  const cameraScale = interpolate(frame, [0, 180], [1.045, 1.075], {extrapolateLeft:'clamp', extrapolateRight:'clamp'});
  const cameraDrift = interpolate(frame, [0, 180], [-5, 5], {extrapolateLeft:'clamp', extrapolateRight:'clamp'});
  const compareOpacity = interpolate(frame, [0, 88, 104], [1, 1, 0], {extrapolateLeft:'clamp', extrapolateRight:'clamp'});
  const diagramOpacity = interpolate(frame, [72, 102], [0, 1], {extrapolateLeft:'clamp', extrapolateRight:'clamp'});
  const fenceReveal = interpolate(frame, [0, 38], [0, 1], {extrapolateLeft:'clamp', extrapolateRight:'clamp'});
  const metricOpacity = interpolate(frame, [6, 16, 78, 94], [0, 1, 1, 0], {extrapolateLeft:'clamp', extrapolateRight:'clamp'});
  const dogY = interpolate(frame, [103, 145, 180], [395, 459, 459], {extrapolateLeft:'clamp', extrapolateRight:'clamp'});
  const posts = [360, 520, 680, 840, 1000, 1160, 1320, 1480, 1560];
  const diagramPosts = [250, 430, 610, 790, 970, 1150, 1330, 1510, 1670];

  return (
    <AbsoluteFill style={{backgroundColor:'transparent', overflow:'hidden'}}>
      {src && isVideo && (
        <AbsoluteFill style={{overflow:'hidden'}}>
          <OffthreadVideo
            src={staticFile(src)}
            muted
            startFrom={Math.round((asset.trimStart || 0) * fps)}
            style={{width:'100%', height:'100%', objectFit:'cover', transform:`scale(${cameraScale}) translateX(${cameraDrift}px)`}}
          />
        </AbsoluteFill>
      )}
      {src && !isVideo && (
        <AbsoluteFill style={{overflow:'hidden'}}>
          <Img
            src={staticFile(src)}
            style={{width:'100%', height:'100%', objectFit:'cover', transform:`scale(${cameraScale}) translateX(${cameraDrift}px)`}}
          />
        </AbsoluteFill>
      )}
      {!src && !hasMapBackground && (
        <AbsoluteFill style={{background:'linear-gradient(180deg, #25271f 0%, #3b382b 48%, #23372a 100%)'}} />
      )}
      <AbsoluteFill style={{pointerEvents:'none'}}>
        <svg width="1920" height="1080" viewBox="0 0 1920 1080" aria-hidden="true">
          {/* Qualitative length comparison: the drawn spans are illustrative, not a scale. */}
          <g opacity={compareOpacity}>
            <text x="960" y="292" textAnchor="middle" fill="#f4eddb" fontFamily="Arial, sans-serif" fontSize="82" fontWeight="700" letterSpacing="2" opacity={metricOpacity}>5,600 km</text>
            <line x1="360" y1="470" x2="1620" y2="470" stroke="#d9c9a4" strokeWidth="5" strokeDasharray="1260" strokeDashoffset={1260 * (1-fenceReveal)} />
            <line x1="360" y1="505" x2="1620" y2="505" stroke="#d9c9a4" strokeWidth="2" strokeDasharray="1260" strokeDashoffset={1260 * (1-fenceReveal)} opacity="0.7" />
            {posts.map((x, i) => (
              <g key={`cmp-post-${i}`} opacity={fenceReveal}>
                <line x1={x} y1="448" x2={x} y2="527" stroke="#cfc3a7" strokeWidth="5" />
                <line x1={x-9} y1="527" x2={x+9} y2="527" stroke="#cfc3a7" strokeWidth="3" />
              </g>
            ))}
            <line x1="360" y1="615" x2="1490" y2="615" stroke="#cbbd9f" strokeWidth="7" strokeDasharray="1130" strokeDashoffset={1130 * (1-fenceReveal)} />
            <g opacity={fenceReveal} fill="#cbbd9f">
              {[360, 520, 680, 840, 1000, 1160, 1320, 1480].map((x, i) => <rect key={`stone-${i}`} x={x-30} y="598" width="58" height="34" rx="2" />)}
            </g>
            <text x="960" y="704" textAnchor="middle" fill="#f0e8d5" fontFamily="Arial, sans-serif" fontSize="34" fontWeight="600" letterSpacing="3">LONGER THAN THE GREAT WALL</text>
          </g>

          {/* Abstract causal schematic, not a geographic map. */}
          <g opacity={diagramOpacity}>
            <rect x="220" y="250" width="1480" height="280" fill="rgba(183,128,62,0.22)" />
            <rect x="220" y="590" width="1480" height="250" fill="rgba(60,123,75,0.25)" />
            <text x="285" y="328" fill="#f0d4a5" fontFamily="Arial, sans-serif" fontSize="34" fontWeight="700" letterSpacing="4">DESERT</text>
            <text x="285" y="785" fill="#d6e5cb" fontFamily="Arial, sans-serif" fontSize="34" fontWeight="700" letterSpacing="3">FERTILE SOUTH</text>
            <line x1="240" y1="540" x2="1680" y2="540" stroke="#e0d2b2" strokeWidth="5" strokeDasharray="1440" strokeDashoffset={1440 * (1-fenceReveal)} />
            <line x1="240" y1="559" x2="1680" y2="559" stroke="#e0d2b2" strokeWidth="3" strokeDasharray="1440" strokeDashoffset={1440 * (1-fenceReveal)} />
            {diagramPosts.map((x, i) => (
              <g key={`diagram-post-${i}`} opacity={fenceReveal}>
                <line x1={x} y1="512" x2={x} y2="611" stroke="#d8c8a6" strokeWidth="5" />
                <line x1={x-10} y1="611" x2={x+10} y2="611" stroke="#d8c8a6" strokeWidth="3" />
              </g>
            ))}
            <g transform={`translate(900 ${dogY})`} fill="#28241d" stroke="#28241d" strokeWidth="6" strokeLinecap="round" strokeLinejoin="round">
              <path d="M18 31 C27 18 47 14 68 19 L88 25 L103 17 L113 5 L120 8 L116 24 L107 34 L91 39 L82 53 L77 53 L78 37 L56 38 L48 54 L42 54 L44 36 L29 36 L23 51 L17 51 L19 34 L9 29 L3 16 L8 13 Z" />
              <path d="M28 34 L30 51 M68 35 L67 52" fill="none" />
              <circle cx="101" cy="25" r="2.5" fill="#e5c891" stroke="none" />
            </g>
          </g>
        </svg>
      </AbsoluteFill>
    </AbsoluteFill>
  );
}"}
